<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';$u=require_login();$s=db()->prepare("SELECT c.*,l.title,l.id listing_id,CASE WHEN c.buyer_id=? THEN seller.name ELSE buyer.name END other_name,(SELECT message FROM messages WHERE conversation_id=c.id ORDER BY id DESC LIMIT 1) last_message,(SELECT created_at FROM messages WHERE conversation_id=c.id ORDER BY id DESC LIMIT 1) last_at,(SELECT COUNT(*) FROM messages WHERE conversation_id=c.id AND sender_id<>? AND is_read=0) unread FROM conversations c JOIN listings l ON l.id=c.listing_id JOIN users buyer ON buyer.id=c.buyer_id JOIN users seller ON seller.id=c.seller_id WHERE c.buyer_id=? OR c.seller_id=? ORDER BY COALESCE(last_at,c.created_at) DESC");$s->execute([$u['id'],$u['id'],$u['id'],$u['id']]);$items=$s->fetchAll();$pageTitle='Messages';include __DIR__.'/includes/header.php';?><div class="section-head"><div><h2>Messages</h2><p>Your buyer-seller conversations.</p></div></div><div class="stack"><?php foreach($items as $c):?><a class="card card-body" href="/chat.php?conversation_id=<?=$c['id']?>"><strong><?=e($c['other_name'])?> · <?=e($c['title'])?></strong><div class="muted"><?=e($c['last_message'] ?: 'Start the conversation')?><?php if($c['unread']):?> · <?=$c['unread']?> unread<?php endif;?></div></a><?php endforeach;?></div><?php if(!$items):?><div class="empty">No conversations yet.</div><?php endif;?><?php include __DIR__.'/includes/footer.php';?>